pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps that are likely to remain empty (the "dead space" penalty).
    // Small residuals (1-9) are often unusable since min item size is 10.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        100.0 / post
    } else {
        0.0
    };

    // Reward tighter fits that align with the lookahead item.
    // If the next item fits in the current post_residual, prioritize this bin.
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -50.0 * (post / bin_capacity as f64)
    } else {
        0.0
    };

    // Dynamic pressure: As the stream progresses, become more conservative about 
    // opening new bins. If bin_residual == bin_capacity, this is a new bin.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As we reach the end of the stream, opening a new bin is increasingly costly.
        20.0 + (50.0 * progress) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Combine factors:
    // 1. Prefer smaller post_residual (Best Fit principle).
    // 2. Add non-linear coupling with progress for new bin thresholding.
    // 3. Apply lookahead and dead-space penalties.
    let mut score = post + dead_space_penalty + lookahead_bonus + new_bin_penalty;

    // Apply a slight bias against having too many open bins if we are deep in the stream
    if !is_new_bin {
        score += (open_bins_count as f64 * progress * 2.0);
    }

    score
}

