pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the post_residual, but prioritize tight fits that leave room for the next item.
    // If a bin is new (bin_residual == bin_capacity), it is a last resort.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only do it if the existing bins leave "bad" residuals.
    if is_new_bin {
        // Only consider a new bin if the average residual of current bins is already very small (tight),
        // or if we have no other fitting bins.
        score += 45.0; 
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Harmonic logic: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps pack future items better.
    let harmonic_penalty = if post_residual > 0 {
        let r = post_residual as f64;
        let mod_val = (r % 20.0).min(r % 25.0).min(r % 33.0);
        mod_val * 0.5
    } else {
        -10.0 // Strong reward for perfect fits
    };
    score += harmonic_penalty;

    // Lookahead logic: if the next item is large, avoid leaving a residual smaller than it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 * (next_item_size as f64 / (post_residual + 1) as f64);
    }

    // Prefer bins that keep the mean_residual high enough to accommodate future unknown items.
    if mean_residual > 0.0 && !is_new_bin {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead-aware penalties.
    // 1. Prioritize tight fits (minimize post_residual).
    // 2. Penalize creating "fragmented" bins that cannot fit the next item.
    // 3. Dynamic scaling based on progression to favor consolidation late in the stream.

    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Penalty for leaving space that is too small for the next item (Dead Space Penalty)
    if next_item_size > 0 && post_residual < next_item_size {
        // If this bin becomes a "dead" bin for the next item, penalize it.
        // We scale the penalty by how many bins are currently open.
        score += (next_item_size - post_residual) as f64 * (1.0 + progress);
    }

    // Heuristic for New Bin Candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "too full" to handle the lookahead efficiently.
        // If mean_residual is small, it's better to force a new bin to accommodate future large items.
        if mean_residual < (item_size as f64 * 0.8) && open_bins_count > 0 {
            score += 25.0; // Heavily penalize opening a new bin prematurely
        } else {
            score -= 5.0; // Encourage opening if current bins are cluttered
        }
    } else {
        // If this is the last chance for this item (fitting_bins_count == 1), 
        // we heavily prioritize this bin to avoid opening a new one unnecessarily.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Dynamic constraint: As we approach the end of the stream, prioritize packing density
    // over fragmentation avoidance.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins, but penalize "near-empty" spaces (e.g., 1-9)
    // that are too small to fit common items (10+).

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (unusable space < 10)
    // If the post_residual is between 1 and 9, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: If we are near the end of the stream, prioritize closing bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Penalty for opening new bins: Only open if the fit is exceptionally good (near 0 residual)
    // or if the current bin count is low relative to the potential space.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // We only pick this if the average residual of existing bins is already high,
        // or if we have very few bins open.
        score += 25.0 + (mean_residual * 0.5) - (open_bins_count as f64 * 0.5);
    }

    // Lookahead logic: If we know the next item, penalize bins that cannot fit it
    // if that bin is one of the few that could have accommodated the current item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Discourage creating too many fragmented bins by penalizing high open_bins_count
    score += (open_bins_count as f64) * 2.0;

    // Reward bins that have residuals close to the mean, promoting uniform filling
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}
